import urllib.parse


class UrlPath:
    def __init__(self):
        self.segments = []
        self.with_end_tag = False

    def add(self, segment):
        self.segments.append(self.fix_path(segment))

    def parse(self, path, charset):
        if path:
            self._update_end_tag_from_path(path)
            fixed_path = self.fix_path(path)
            if fixed_path:
                self._append_segments_from_path(fixed_path, charset)

    def _update_end_tag_from_path(self, path):
        if path.endswith('/'):
            self.with_end_tag = True

    def _append_segments_from_path(self, path, charset):
        segments = path.split('/')
        for seg in segments:
            decoded_seg = urllib.parse.unquote(seg, encoding=charset)
            self._add_segment(decoded_seg)

    def _add_segment(self, segment):
        self.segments.append(segment)

    @staticmethod
    def fix_path(path):
        if not path:
            return ''
        return path.strip('/')

    def get_segments(self):
        return list(self.segments)

    def set_end_tag(self, value):
        self.with_end_tag = bool(value)

    def is_with_end_tag(self):
        return self.with_end_tag
